int nondet_int(void);

int main(void) {
  int x = nondet_int();
  int y = nondet_int();
  assert(x * y == y * x);      /* theorem; bit-blasting groans */
  return 0;
}

=== benchmarks/c-straightline/order.c ===
#include <assert.h>
int nondet_int(void);

int main(void) {
  int a = nondet_int();
  int b = nondet_int();
  if (a >= 0 && b >= 0 && a < 10000 && b < 10000) {
    int lo = a < b ? a : b;
    int hi = a < b ? b : a;
    assert(lo <= hi);
  }
  return 0;
}

