#include <assert.h>
int nondet_int(void);

int main(void) {
  int n = nondet_int();
  if (n >= 0 && n <= 30) {
    int s = 0;
    for (int i = 0; i < n; i++) s += 3;
    assert(s % 3 == 0);        /* invariant: s is a multiple of 3 */
  }
  return 0;
