            self.take()
            self.eat('(')
            e = self.expr()
            self.eat(')')
            self.eat(';')
            return ('assert', e)
        if v == 'return':
            self.take()
            e = None if self.cur() == ';' else self.expr()
            self.eat(';')
            return ('return', e)
        if v == ';':
            self.take()
            return ('empty',)
        e = self.expr()
        self.eat(';')
        return ('expr', e)

