    def rel(self):
        return self._binlevel(self.shift, ('<', '>', '<=', '>='))

    def shift(self):
        return self._binlevel(self.add, ('<<', '>>'))

    def add(self):
        return self._binlevel(self.mul, ('+', '-'))

    def mul(self):
        return self._binlevel(self.unary, ('*', '/', '%'))

