a Z3 bitvector symbolic executor instead of concrete evaluation. Loops are
unrolled with explicit state-freezing (ite merge) up to a bound; a
"residual" formula captures whether the loop guard could still be true
after that many iterations (the analogue of cbmc's unwinding assertion).
Kept deliberately separate from the cbmc-based solver and from the
language's own interpreter so a verdict from each rests on a different
codebase."""
import re

import z3

MASK = 0xFFFFFFFF
COMPOUND = {'+=': '+', '-=': '-', '*=': '*', '/=': '/', '%=': '%',
            '&=': '&', '|=': '|', '^=': '^', '<<=': '<<', '>>=': '>>'}

TOKEN_RE = re.compile(r"""
    (?P<NUM>\d+)
  | (?P<ID>[A-Za-z_]\w*)
  | (?P<OP><<=|>>=|==|!=|<=|>=|&&|\|\||\+\+|--|\+=|-=|\*=|/=|%=|&=|\|=|\^=|<<|>>|[-+*/%&|^~!<>=(){}\[\];,?:])
  | (?P<WS>\s+)
""", re.VERBOSE)


def extract_main_body(src):
    nc = re.sub(r'/\*.*?\*/', ' ', src, flags=re.DOTALL)
    nc = re.sub(r'//[^\n]*', ' ', nc)
    m = re.search(r'\bint\s+main\s*\(\s*(?:void)?\s*\)\s*\{', nc)
    if not m:
        raise ValueError('no main() found')
    depth, j = 1, m.end()
    while depth > 0:
        if nc[j] == '{':
            depth += 1
        elif nc[j] == '}':
            depth -= 1
        j += 1
    return nc[m.end():j - 1]


def lex(s):
    toks, pos, n = [], 0, len(s)
    while pos < n:
        m = TOKEN_RE.match(s, pos)
        if not m:
            raise ValueError(f'bad token at {pos}')
        pos = m.end()
        if m.lastgroup != 'WS':
            toks.append((m.lastgroup, m.group()))
    toks.append(('EOF', ''))
    return toks


class Parser:
    """Recursive descent over the standard C precedence ladder, restricted
    to int arithmetic/bitwise/logic ops, if/for/while, assert, decl."""

    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def cur(self):
        return self.t[self.i][1]

    def take(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def eat(self, v):
        if self.cur() != v:
            raise ValueError(f'expected {v!r}, found {self.cur()!r}')
        return self.take()

    def program(self):
        out = []
        while self.cur() != '':
            out.append(self.stmt())
        return out

    def stmt(self):
        v = self.cur()
        if v == '{':
            self.take()
            body = []
            while self.cur() != '}':
                body.append(self.stmt())
            self.take()
            return ('block', body)
        if v == 'if':
            self.take()
            self.eat('(')
            c = self.expr()
            self.eat(')')
            th = self.stmt()
            el = None
            if self.cur() == 'else':
                self.take()
                el = self.stmt()
            return ('if', c, th, el)
        if v == 'for':
            self.take()
            self.eat('(')
            init = None if self.cur() == ';' else self.for_init()
            self.eat(';')
            cond = None if self.cur() == ';' else self.expr()
            self.eat(';')
            upd = None if self.cur() == ')' else self.expr()
            self.eat(')')
            return ('for', init, cond, upd, self.stmt())
        if v == 'while':
            self.take()
            self.eat('(')
            c = self.expr()
            self.eat(')')
            return ('while', c, self.stmt())
        if v == 'int':
            self.take()
            name = self.take()[1]
            e = None
            if self.cur() == '=':
                self.take()
                e = self.expr()
            self.eat(';')
            return ('decl', name, e)
        if v == 'assert':
            self.take()
            self.eat('(')
            e = self.expr()
            self.eat(')')
            self.eat(';')
            return ('assert', e)
        if v == 'return':
            self.take()
            e = None if self.cur() == ';' else self.expr()
            self.eat(';')
            return ('return', e)
        if v == ';':
            self.take()
            return ('empty',)
        e = self.expr()
        self.eat(';')
        return ('expr', e)

    def for_init(self):
        if self.cur() == 'int':
            self.take()
            name = self.take()[1]
            self.eat('=')
            return ('decl', name, self.expr())
        return ('expr', self.expr())

    def expr(self):
        return self.assign()

    def assign(self):
        left = self.ternary()
        v = self.cur()
        if v == '=':
            self.take()
            if left[0] != 'var':
                raise ValueError('bad assignment target')
            return ('assign', left[1], self.assign())
